<?php
/** Safe media and playlist helpers for Extended File Manager. */
function efm_video_root($settings) { $root = isset($settings['videoDirectory']) ? $settings['videoDirectory'] : ''; $media = isset($settings['mediaDirectory']) ? realpath($settings['mediaDirectory']) : false; $real = $root !== '' ? realpath($root) : false; if ($media === false || $real === false || !is_dir($media) || !is_dir($real)) return false; return ($real === $media || strpos($real, $media . DIRECTORY_SEPARATOR) === 0) ? rtrim($real, DIRECTORY_SEPARATOR) : false; }
function efm_relative_path($value) { if (!is_string($value) || $value === '' || strpos($value, "\0") !== false || strpos($value, '\\') !== false) return false; if ($value[0] === '/' || preg_match('/(^|\/)\.\.?($|\/)/', $value)) return false; return ltrim($value, '/'); }
function efm_path_inside($root, $relative, $mustBeFile = false) { $relative = efm_relative_path($relative); if ($relative === false || $root === false) return false; $cursor = $root; foreach (explode('/', $relative) as $part) { $cursor .= DIRECTORY_SEPARATOR . $part; if (is_link($cursor)) return false; } $candidate = realpath($cursor); if ($candidate === false || ($candidate !== $root && strpos($candidate, $root . DIRECTORY_SEPARATOR) !== 0)) return false; if ($mustBeFile && !is_file($candidate)) return false; return $candidate; }
function efm_video_extension($name) { return preg_match('/\.(avi|m4v|mkv|mov|mp4|mpeg|mpg|ts|webm)$/i', $name) === 1; }
function efm_list_media($root, $relative) { $relative = $relative === '' ? '' : efm_relative_path($relative); if ($relative === false) return false; $directory = $relative === '' ? $root : efm_path_inside($root, $relative); if ($directory === false || !is_dir($directory)) return false; $items = array(); $entries = scandir($directory); if ($entries === false) return $items; foreach ($entries as $entry) { if ($entry === '.' || $entry === '..' || strpos($entry, "\0") !== false) continue; $childRelative = $relative === '' ? $entry : $relative . '/' . $entry; $child = $directory . DIRECTORY_SEPARATOR . $entry; if (is_link($child)) continue; if (is_dir($child)) $items[] = array('type'=>'directory','name'=>$entry,'path'=>$childRelative); elseif (is_file($child) && efm_video_extension($entry) && efm_path_inside($root, $childRelative, true) !== false) $items[] = array('type'=>'file','name'=>$entry,'path'=>$childRelative,'size'=>filesize($child)); } usort($items, function($a,$b) { if ($a['type'] !== $b['type']) return $a['type'] === 'directory' ? -1 : 1; return strnatcasecmp($a['name'],$b['name']); }); return $items; }
function efm_playlist_name($value) { return is_string($value) && preg_match('/^[A-Za-z0-9][A-Za-z0-9 _.-]{0,127}$/', $value) ? $value : false; }
function efm_add_to_playlist($settings, $playlistName, $paths) { $root=efm_video_root($settings); $playlistName=efm_playlist_name($playlistName); if ($root===false || $playlistName===false || !is_array($paths) || count($paths)<1 || count($paths)>500) return array('ok'=>false,'error'=>'Invalid playlist or media selection.'); $valid=array(); foreach($paths as $path) { $path=efm_relative_path($path); if($path===false || efm_path_inside($root,$path,true)===false || !efm_video_extension($path)) return array('ok'=>false,'error'=>'One or more selected files are not safe video files.'); if(!in_array($path,$valid,true)) $valid[]=$path; } $media=isset($settings['mediaDirectory'])?realpath($settings['mediaDirectory']):false; $dir=isset($settings['playlistDirectory'])?realpath($settings['playlistDirectory']):false; if($media===false || $dir===false || !is_dir($media) || !is_dir($dir) || ($dir!==$media && strpos($dir,$media.DIRECTORY_SEPARATOR)!==0)) return array('ok'=>false,'error'=>'FPP playlist directory is unavailable or outside media storage.'); $file=$dir.DIRECTORY_SEPARATOR.$playlistName.'.json'; if(!is_file($file) || is_link($file)) return array('ok'=>false,'error'=>'Playlist does not exist or is a symlink.'); $handle=fopen($file,'c+'); if($handle===false || !flock($handle,LOCK_EX)) return array('ok'=>false,'error'=>'Could not lock playlist.'); $playlist=json_decode(stream_get_contents($handle),true); if(!is_array($playlist)) { flock($handle,LOCK_UN); fclose($handle); return array('ok'=>false,'error'=>'Playlist JSON is invalid.'); } if(!isset($playlist['mainPlaylist']) || !is_array($playlist['mainPlaylist'])) $playlist['mainPlaylist']=array(); $existing=array(); foreach($playlist['mainPlaylist'] as $entry) if(is_array($entry)&&isset($entry['mediaName'])) $existing[$entry['mediaName']]=true; $added=0; foreach($valid as $path) { if(isset($existing[$path])) continue; $playlist['mainPlaylist'][]=array('type'=>'media','enabled'=>1,'playOnce'=>0,'mediaName'=>$path,'duration'=>0); $existing[$path]=true; $added++; } $playlist['name']=isset($playlist['name'])?$playlist['name']:$playlistName; $playlist['version']=isset($playlist['version'])?$playlist['version']:3; if(!isset($playlist['playlistInfo'])||!is_array($playlist['playlistInfo'])) $playlist['playlistInfo']=array(); $playlist['playlistInfo']['mainPlaylist_items']=count($playlist['mainPlaylist']); $playlist['playlistInfo']['total_items']=count($playlist['mainPlaylist'])+count(isset($playlist['leadIn'])&&is_array($playlist['leadIn'])?$playlist['leadIn']:array())+count(isset($playlist['leadOut'])&&is_array($playlist['leadOut'])?$playlist['leadOut']:array()); $encoded=json_encode($playlist,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES); $temporary=tempnam($dir,'.efm-playlist-'); if($encoded===false || $temporary===false || file_put_contents($temporary,$encoded,LOCK_EX)!==strlen($encoded) || !rename($temporary,$file)) { if($temporary!==false && is_file($temporary)) unlink($temporary); flock($handle,LOCK_UN); fclose($handle); return array('ok'=>false,'error'=>'Could not safely write playlist.'); } flock($handle,LOCK_UN); fclose($handle); return array('ok'=>true,'added'=>$added,'skipped'=>count($valid)-$added,'playlist'=>$playlistName); }
